import { atom } from 'jotai'
import type { CalendarEvent, CalendarView, FilterMode } from './calendar-1.types'
import { MOCK_EVENTS } from './calendar-data'

export const eventsAtom = atom<CalendarEvent[]>(MOCK_EVENTS)
export const viewedDateAtom = atom<Date>(new Date(2026, 2, 10))
export const calendarViewAtom = atom<CalendarView>('month')
export const filterModeAtom = atom<FilterMode>('all')

export const addEventDateAtom = atom<string | null>(null)
export const editingEventAtom = atom<CalendarEvent | null>(null)
export const isAddEventOpenAtom = atom<boolean>(false)
export const overflowDayAtom = atom<string | null>(null)
export const commandOpenAtom = atom<boolean>(false)

export const filteredEventsAtom = atom<CalendarEvent[]>((get) => {
  const events = get(eventsAtom)
  const filter = get(filterModeAtom)
  if (filter === 'shared') return events.filter((e) => e.starred)
  return events
})

export const showEmptyStateAtom = atom<boolean>((get) => {
  const filter = get(filterModeAtom)
  return filter === 'public' || filter === 'archived'
})

export function formatHour(h: number): string {
  if (h === 0) return '12 AM'
  if (h < 12) return `${h} AM`
  if (h === 12) return '12 PM'
  return `${h - 12} PM`
}

// YYYY-MM-DD -> Date at midnight local time
export function parseDateStr(s: string): Date | null {
  if (!s) return null
  const d = new Date(`${s}T00:00:00`)
  return Number.isNaN(d.getTime()) ? null : d
}

// "9:00 AM" -> "09:00"
export function timeStringTo24h(time: string): string {
  const m = time.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i)
  if (!m) return '09:00'
  let h = Number.parseInt(m[1] ?? '0', 10)
  const min = m[2] ?? '00'
  const p = m[3]?.toUpperCase()
  if (p === 'PM' && h !== 12) h += 12
  if (p === 'AM' && h === 12) h = 0
  return `${String(h).padStart(2, '0')}:${min}`
}

// "14:30" -> "2:30 PM"
export function time24hToDisplay(t: string): string {
  const [hStr, mStr] = t.split(':')
  let h = Number.parseInt(hStr ?? '9', 10)
  const min = mStr ?? '00'
  const p = h >= 12 ? 'PM' : 'AM'
  if (h === 0) h = 12
  else if (h > 12) h -= 12
  return `${h}:${min} ${p}`
}

'use client'

import { Card } from '@gentleduck/registry-ui/card'
import { Separator } from '@gentleduck/registry-ui/separator'
import { CalendarIcon } from 'lucide-react'
import * as React from 'react'
import { type CalendarEvent, type CalendarView, type FilterMode, MOCK_EVENTS } from './calendar-data'
import { CalendarCommandMenu } from './components/calendar-command-menu'
import { CalendarDayView } from './components/calendar-day-view'
import { CalendarEventDialog } from './components/calendar-event-dialog'
import { CalendarGrid } from './components/calendar-grid'
import { CalendarToolbar } from './components/calendar-toolbar'
import { CalendarWeekView } from './components/calendar-week-view'
import { CalendarYearView } from './components/calendar-year-view'

export default function Page() {
  const [events, setEvents] = React.useState<CalendarEvent[]>(MOCK_EVENTS)
  const [viewedDate, setViewedDate] = React.useState<Date>(new Date(2025, 0, 10))
  const [calendarView, setCalendarView] = React.useState<CalendarView>('month')
  const [filterMode, setFilterMode] = React.useState<FilterMode>('all')
  const [addEventDate, setAddEventDate] = React.useState<string | null>(null)
  const [editingEvent, setEditingEvent] = React.useState<CalendarEvent | null>(null)
  const [isAddEventOpen, setIsAddEventOpen] = React.useState(false)
  const [overflowDay, setOverflowDay] = React.useState<string | null>(null)
  const [commandOpen, setCommandOpen] = React.useState(false)

  React.useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setCommandOpen(true)
      }
    }
    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [])

  const filteredEvents = React.useMemo(() => {
    if (filterMode === 'shared') return events.filter((e) => e.starred)
    return events
  }, [events, filterMode])

  function handlePrev() {
    setViewedDate((d) => {
      const n = new Date(d)
      switch (calendarView) {
        case 'day':
          n.setDate(n.getDate() - 1)
          break
        case 'week':
          n.setDate(n.getDate() - 7)
          break
        case 'month':
          n.setMonth(n.getMonth() - 1)
          break
        case 'year':
          n.setFullYear(n.getFullYear() - 1)
          break
      }
      return n
    })
  }
  function handleNext() {
    setViewedDate((d) => {
      const n = new Date(d)
      switch (calendarView) {
        case 'day':
          n.setDate(n.getDate() + 1)
          break
        case 'week':
          n.setDate(n.getDate() + 7)
          break
        case 'month':
          n.setMonth(n.getMonth() + 1)
          break
        case 'year':
          n.setFullYear(n.getFullYear() + 1)
          break
      }
      return n
    })
  }
  function handleToday() {
    setViewedDate(new Date())
  }
  function handleDayClick(dateStr: string) {
    setAddEventDate(dateStr)
    setEditingEvent(null)
    setIsAddEventOpen(true)
  }
  function handleSaveEvent(event: CalendarEvent) {
    setEvents((prev) => {
      const idx = prev.findIndex((e) => e.id === event.id)
      if (idx >= 0) {
        const next = [...prev]
        next[idx] = event
        return next
      }
      return [...prev, event]
    })
  }
  function handleDeleteEvent(id: string) {
    setEvents((prev) => prev.filter((e) => e.id !== id))
  }
  function handleEditEvent(event: CalendarEvent) {
    setEditingEvent(event)
    setAddEventDate(null)
    setIsAddEventOpen(true)
  }
  function handleMonthClick(month: number) {
    setViewedDate(new Date(viewedDate.getFullYear(), month, 1))
    setCalendarView('month')
  }
  function handleNavigateToDate(dateStr: string) {
    const d = new Date(`${dateStr}T00:00:00`)
    setViewedDate(d)
    if (calendarView === 'year') setCalendarView('month')
  }

  const showEmptyState = filterMode === 'public' || filterMode === 'archived'

  return (
    <div className="mx-auto flex h-screen w-full max-w-7xl flex-col items-center justify-center">
      <Card className="gap-0 p-0">
        {/* Toolbar - single row with everything */}
        <div className="p-4">
          <CalendarToolbar
            viewedDate={viewedDate}
            calendarView={calendarView}
            filterMode={filterMode}
            onPrev={handlePrev}
            onNext={handleNext}
            onToday={handleToday}
            onViewChange={setCalendarView}
            onFilterChange={setFilterMode}
            onSearchOpen={() => setCommandOpen(true)}
            onAddEvent={() => {
              setEditingEvent(null)
              setAddEventDate(null)
              setIsAddEventOpen(true)
            }}
          />
        </div>
        <Separator />

        {/* Calendar content */}
        <div>
          {showEmptyState ? (
            <div className="flex min-h-96 flex-col items-center justify-center gap-2 rounded-xl border border-dashed bg-card">
              <CalendarIcon className="size-12 text-muted-foreground/30" />
              <p className="text-muted-foreground text-sm">No {filterMode} events yet</p>
            </div>
          ) : calendarView === 'month' ? (
            <CalendarGrid
              viewedMonth={viewedDate}
              events={filteredEvents}
              overflowDay={overflowDay}
              onOverflowChange={setOverflowDay}
              onDayClick={handleDayClick}
              onEditEvent={handleEditEvent}
              onDeleteEvent={handleDeleteEvent}
            />
          ) : calendarView === 'week' ? (
            <CalendarWeekView
              viewedDate={viewedDate}
              events={filteredEvents}
              onDayClick={handleDayClick}
              onSelectEvent={() => {}}
              onEditEvent={handleEditEvent}
              onDeleteEvent={handleDeleteEvent}
            />
          ) : calendarView === 'day' ? (
            <CalendarDayView
              viewedDate={viewedDate}
              events={filteredEvents}
              onSelectEvent={() => {}}
              onEditEvent={handleEditEvent}
              onDeleteEvent={handleDeleteEvent}
            />
          ) : (
            <CalendarYearView viewedDate={viewedDate} events={filteredEvents} onMonthClick={handleMonthClick} />
          )}
        </div>

        <CalendarCommandMenu
          open={commandOpen}
          onOpenChange={setCommandOpen}
          events={filteredEvents}
          onSelectEvent={(evt) => handleEditEvent(evt)}
          onNavigateToDate={handleNavigateToDate}
        />
        <CalendarEventDialog
          open={isAddEventOpen}
          onOpenChange={setIsAddEventOpen}
          onSave={handleSaveEvent}
          editingEvent={editingEvent}
          defaultDate={addEventDate}
        />
      </Card>
    </div>
  )
}

import type { CalendarEvent } from './calendar-data'

export function getWeeksForMonth(year: number, month: number): Date[][] {
  const firstDay = new Date(year, month, 1)
  const lastDay = new Date(year, month + 1, 0)
  const startDay = new Date(firstDay)
  const dow = startDay.getDay()
  startDay.setDate(startDay.getDate() + (dow === 0 ? -6 : 1 - dow))
  const weeks: Date[][] = []
  const current = new Date(startDay)
  while (current <= lastDay || weeks.length < 5) {
    const week: Date[] = []
    for (let i = 0; i < 7; i++) {
      week.push(new Date(current))
      current.setDate(current.getDate() + 1)
    }
    weeks.push(week)
    if (weeks.length >= 6) break
  }
  return weeks
}

export function getEventsForDay(events: CalendarEvent[], date: Date): CalendarEvent[] {
  const ds = formatDateString(date)
  return events.filter((e) => e.date === ds).sort((a, b) => a.timeValue - b.timeValue)
}

export function formatDateString(date: Date): string {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
}

export function formatMonthYear(date: Date): string {
  return date.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })
}

export function formatDateRange(date: Date): string {
  const first = new Date(date.getFullYear(), date.getMonth(), 1)
  const last = new Date(date.getFullYear(), date.getMonth() + 1, 0)
  const fmt = (d: Date) => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
  return `${fmt(first)} - ${fmt(last)}`
}

export function formatFullDate(dateStr: string): string {
  const d = new Date(`${dateStr}T00:00:00`)
  return d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })
}

export function isToday(date: Date): boolean {
  const n = new Date()
  return date.getFullYear() === n.getFullYear() && date.getMonth() === n.getMonth() && date.getDate() === n.getDate()
}

export function isSameMonth(date: Date, month: Date): boolean {
  return date.getFullYear() === month.getFullYear() && date.getMonth() === month.getMonth()
}

export function parseTimeToMinutes(time: string): number {
  const m = time.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i)
  if (!m) return 0
  let h = Number.parseInt(m[1] ?? '0', 10)
  const min = Number.parseInt(m[2] ?? '0', 10)
  const p = m[3]?.toUpperCase()
  if (p === 'PM' && h !== 12) h += 12
  if (p === 'AM' && h === 12) h = 0
  return h * 60 + min
}

export function isWeekend(date: Date): boolean {
  const d = date.getDay()
  return d === 0 || d === 6
}

export function getWeekStart(date: Date): Date {
  const d = new Date(date)
  const dow = d.getDay()
  d.setDate(d.getDate() - (dow === 0 ? 6 : dow - 1))
  return d
}

export function getDaysForWeek(date: Date): Date[] {
  const start = getWeekStart(date)
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(start)
    d.setDate(d.getDate() + i)
    return d
  })
}

export function formatViewHeading(date: Date, view: string): string {
  switch (view) {
    case 'day':
      return date.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })
    case 'week': {
      const start = getWeekStart(date)
      const end = new Date(start)
      end.setDate(end.getDate() + 6)
      const fmt = (d: Date) => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
      return `${fmt(start)} - ${fmt(end)}, ${end.getFullYear()}`
    }
    case 'year':
      return String(date.getFullYear())
    default:
      return formatMonthYear(date)
  }
}

export function formatViewSubheading(date: Date, view: string): string {
  switch (view) {
    case 'day':
      return ''
    case 'week': {
      const start = getWeekStart(date)
      const end = new Date(start)
      end.setDate(end.getDate() + 6)
      const fmt = (d: Date) => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
      return `${fmt(start)} - ${fmt(end)}`
    }
    case 'year':
      return `Jan 1, ${date.getFullYear()} - Dec 31, ${date.getFullYear()}`
    default:
      return formatDateRange(date)
  }
}

'use client'

import { cn } from '@gentleduck/libs/cn'
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@gentleduck/registry-ui/command'
import { ClockIcon, StarIcon } from 'lucide-react'
import * as React from 'react'
import { CATEGORY_COLORS, CATEGORY_LABELS, type CalendarEvent } from '../calendar-data'
import { formatFullDate } from '../calendar-utils'

interface ICalendarCommandMenuProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  events: CalendarEvent[]
  onSelectEvent: (event: CalendarEvent) => void
  onNavigateToDate: (dateStr: string) => void
}

export function CalendarCommandMenu({
  open,
  onOpenChange,
  events,
  onSelectEvent,
  onNavigateToDate,
}: ICalendarCommandMenuProps) {
  const [query, setQuery] = React.useState('')

  React.useEffect(() => {
    if (!open) setQuery('')
  }, [open])

  const filtered = React.useMemo(() => {
    if (!query) return events.slice(0, 10)
    const q = query.toLowerCase()
    return events.filter((e) => e.title.toLowerCase().includes(q)).slice(0, 20)
  }, [events, query])

  const grouped = React.useMemo(() => {
    const map = new Map<string, CalendarEvent[]>()
    for (const e of filtered) {
      const arr = map.get(e.date) ?? []
      arr.push(e)
      map.set(e.date, arr)
    }
    return Array.from(map.entries()).sort(([a], [b]) => a.localeCompare(b))
  }, [filtered])

  return (
    <CommandDialog open={open} onOpenChange={onOpenChange} shouldFilter={false}>
      <CommandInput
        placeholder="Search events..."
        value={query}
        onInput={(e) => setQuery((e.target as HTMLInputElement).value)}
      />
      <CommandList className="max-h-full">
        <CommandEmpty>No events found.</CommandEmpty>
        {grouped.map(([dateStr, evts]) => (
          <CommandGroup key={dateStr} heading={formatFullDate(dateStr)}>
            {evts.map((evt) => {
              const colors = CATEGORY_COLORS[evt.category]
              return (
                <CommandItem
                  key={evt.id}
                  value={evt.id}
                  onSelect={() => {
                    onSelectEvent(evt)
                    onNavigateToDate(evt.date)
                    onOpenChange(false)
                  }}
                  className="flex items-center gap-3">
                  <span className={cn('size-2 shrink-0 rounded-full', colors.dot)} />
                  <div className="flex flex-1 flex-col">
                    <span className="font-medium text-sm">{evt.title}</span>
                    <span className="text-muted-foreground text-xs">{CATEGORY_LABELS[evt.category]}</span>
                  </div>
                  <div className="flex items-center gap-2 text-muted-foreground text-xs">
                    {evt.starred && <StarIcon className="size-3 fill-amber-400 text-amber-400" />}
                    <ClockIcon className="size-3" />
                    <span>{evt.time}</span>
                  </div>
                </CommandItem>
              )
            })}
          </CommandGroup>
        ))}
      </CommandList>
    </CommandDialog>
  )
}

'use client'

import { cn } from '@gentleduck/libs/cn'
import * as React from 'react'
import type { CalendarEvent } from '../calendar-data'
import { formatDateString, isSameMonth, isToday, isWeekend } from '../calendar-utils'
import { CalendarEventChip } from './calendar-event-chip'
import { CalendarEventDetail } from './calendar-event-detail'
import { CalendarOverflow } from './calendar-overflow'

interface ICalendarDayCellProps {
  date: Date
  viewedMonth: Date
  events: CalendarEvent[]
  overflowDay: string | null
  onOverflowChange: (day: string | null) => void
  onDayClick: (dateStr: string) => void
  onEditEvent: (event: CalendarEvent) => void
  onDeleteEvent: (id: string) => void
}

function EventChipWithPopover({
  event,
  onEdit,
  onDelete,
}: {
  event: CalendarEvent
  onEdit: (event: CalendarEvent) => void
  onDelete: (id: string) => void
}) {
  const [open, setOpen] = React.useState(false)
  return (
    <CalendarEventDetail event={event} open={open} onOpenChange={setOpen} onEdit={onEdit} onDelete={onDelete}>
      <div>
        <CalendarEventChip event={event} onSelect={() => setOpen(true)} />
      </div>
    </CalendarEventDetail>
  )
}

export function CalendarDayCell({
  date,
  viewedMonth,
  events,
  overflowDay,
  onOverflowChange,
  onDayClick,
  onEditEvent,
  onDeleteEvent,
}: ICalendarDayCellProps) {
  const inMonth = isSameMonth(date, viewedMonth)
  const today = isToday(date)
  const wkend = isWeekend(date)
  const dateStr = formatDateString(date)

  const hasOverflow = events.length > 3
  const visible = hasOverflow ? events.slice(0, 2) : events.slice(0, 3)
  const hiddenCount = events.length - visible.length

  return (
    // biome-ignore lint/a11y/useSemanticElements: WAI-ARIA grid pattern requires div with role="gridcell"
    <div
      role="gridcell"
      tabIndex={inMonth ? 0 : -1}
      className={cn(
        'flex min-h-28 flex-col overflow-hidden border-border border-r p-1.5 transition-colors last:border-r-0',
        today && 'bg-primary/10 ring-1 ring-primary/30 ring-inset',
        wkend && !today && 'bg-muted/20',
        !inMonth && 'opacity-40',
        inMonth && !today && 'cursor-pointer hover:bg-accent/30',
        inMonth && today && 'cursor-pointer hover:bg-primary/15',
      )}
      onClick={() => {
        if (inMonth) onDayClick(dateStr)
      }}
      onKeyDown={(e) => {
        if (inMonth && (e.key === 'Enter' || e.key === ' ')) {
          e.preventDefault()
          onDayClick(dateStr)
        }
      }}>
      <div className="mb-1 flex shrink-0 justify-start">
        <span
          className={cn(
            'flex size-7 items-center justify-center rounded-full font-medium text-xs',
            today && 'bg-primary font-bold text-primary-foreground shadow-sm',
            !today && inMonth && 'text-foreground',
            !today && !inMonth && 'text-muted-foreground',
          )}>
          {date.getDate()}
        </span>
      </div>
      <div className="flex min-h-0 flex-1 flex-col gap-0.5 overflow-hidden">
        {visible.map((evt) => (
          <EventChipWithPopover key={evt.id} event={evt} onEdit={onEditEvent} onDelete={onDeleteEvent} />
        ))}
        {hiddenCount > 0 && (
          <CalendarOverflow
            events={events}
            hiddenCount={hiddenCount}
            open={overflowDay === dateStr}
            onOpenChange={(o) => onOverflowChange(o ? dateStr : null)}
            onEditEvent={onEditEvent}
            onDeleteEvent={onDeleteEvent}
          />
        )}
      </div>
    </div>
  )
}

'use client'

import { cn } from '@gentleduck/libs/cn'
import * as React from 'react'
import { CATEGORY_COLORS, type CalendarEvent } from '../calendar-data'
import { getEventsForDay } from '../calendar-utils'
import { CalendarEventDetail } from './calendar-event-detail'

interface ICalendarDayViewProps {
  viewedDate: Date
  events: CalendarEvent[]
  onSelectEvent: (event: CalendarEvent) => void
  onEditEvent: (event: CalendarEvent) => void
  onDeleteEvent: (id: string) => void
}

const HOURS = Array.from({ length: 24 }, (_, i) => i)
const HOUR_HEIGHT = 60

import { formatHour } from '../calendar-1.libs'

function EventBlock({
  event,
  onEdit,
  onDelete,
}: {
  event: CalendarEvent
  onEdit: (e: CalendarEvent) => void
  onDelete: (id: string) => void
}) {
  const [open, setOpen] = React.useState(false)
  const colors = CATEGORY_COLORS[event.category]
  const top = (event.timeValue / 60) * HOUR_HEIGHT

  return (
    <CalendarEventDetail event={event} open={open} onOpenChange={setOpen} onEdit={onEdit} onDelete={onDelete}>
      <button
        type="button"
        className={cn(
          'absolute right-4 left-1 z-10 rounded-lg px-3 py-1.5 text-left text-xs shadow-sm transition-shadow hover:shadow-md',
          colors.bg,
          colors.text,
        )}
        style={{ top, minHeight: HOUR_HEIGHT * 0.7 }}
        onClick={() => setOpen(true)}>
        <p className="truncate font-semibold">{event.title}</p>
        <p className="text-[10px] opacity-60">{event.time}</p>
      </button>
    </CalendarEventDetail>
  )
}

export function CalendarDayView({
  viewedDate,
  events,
  onSelectEvent: _onSelectEvent,
  onEditEvent,
  onDeleteEvent,
}: ICalendarDayViewProps) {
  const dayEvents = getEventsForDay(events, viewedDate)

  return (
    <div className="overflow-hidden rounded-xl border bg-card shadow-sm">
      <div className="border-b bg-muted/50 px-4 py-2.5 text-center font-semibold text-sm">
        {viewedDate.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}
      </div>
      <div className="max-h-[700px] overflow-y-auto">
        <div className="relative flex">
          {/* Hour labels */}
          <div className="w-16 shrink-0">
            {HOURS.map((hour) => (
              <div key={hour} className="relative border-border/50 border-b" style={{ height: HOUR_HEIGHT }}>
                <span className="absolute -top-3 right-2 text-[11px] text-muted-foreground">
                  {hour > 0 ? formatHour(hour) : ''}
                </span>
              </div>
            ))}
          </div>
          {/* Timeline */}
          <div className="relative flex-1 border-l">
            {HOURS.map((hour) => (
              <div key={hour} className="border-border/50 border-b" style={{ height: HOUR_HEIGHT }} />
            ))}
            {dayEvents.map((evt) => (
              <EventBlock key={evt.id} event={evt} onEdit={onEditEvent} onDelete={onDeleteEvent} />
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { cn } from '@gentleduck/libs/cn'
import { StarIcon } from 'lucide-react'
import { CATEGORY_COLORS, type CalendarEvent } from '../calendar-data'

interface ICalendarEventChipProps {
  event: CalendarEvent
  onSelect: (event: CalendarEvent) => void
}

export function CalendarEventChip({ event, onSelect }: ICalendarEventChipProps) {
  const colors = CATEGORY_COLORS[event.category]
  return (
    <button
      type="button"
      tabIndex={0}
      className={cn(
        'flex w-full items-center gap-1.5 rounded-md px-1.5 py-1 text-left text-[11px] leading-tight',
        'cursor-pointer transition-all hover:shadow-sm',
        colors.bg,
      )}
      onClick={(e) => {
        e.stopPropagation()
        onSelect(event)
      }}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          e.stopPropagation()
          onSelect(event)
        }
      }}>
      {event.starred ? (
        <StarIcon className={cn('size-2.5 shrink-0 fill-current', colors.text)} />
      ) : (
        <span className={cn('size-1.5 shrink-0 rounded-full', colors.dot)} />
